// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Milestone 5 (three-tier parity ExecPlan): mark joins for EXISTS / NOT EXISTS / MINUS whose subplan is NOT a single
 * pattern (single patterns already have the membership/adjacency tiers). With {@code rdf4j.lmdb.markJoin.enabled} the
 * subplan must be swept ONCE after the distinct-miss threshold and every later probe answered from the mark table, with
 * results identical to the generic evaluator — including bag cardinality of the outer stream.
 */
class LmdbNativeMarkJoinTest {

	private static final String EX = "http://example.com/markjoin/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String MARK_FLAG = SubplanMarkProbe.ENABLED_PROPERTY;

	private static final String EXISTS_QUERY = "SELECT ?s ?m WHERE { ?s <" + EX + "p> ?m . FILTER EXISTS { ?m <" + EX
			+ "q> ?w . ?w <" + EX + "r> ?z } }";
	private static final String NOT_EXISTS_QUERY = "SELECT ?s ?m WHERE { ?s <" + EX + "p> ?m . FILTER NOT EXISTS { ?m <"
			+ EX + "q> ?w . ?w <" + EX + "r> ?z } }";
	private static final String MINUS_QUERY = "SELECT ?s ?m WHERE { ?s <" + EX + "p> ?m MINUS { ?s <" + EX
			+ "pBad> ?y . ?y <" + EX + "flag> ?f } }";
	/** The second UNION branch never binds ?m, so a swept row would match any probe key: the sweep must abort. */
	private static final String UNION_EXISTS_QUERY = "SELECT ?s ?m WHERE { ?s <" + EX + "p> ?m . FILTER EXISTS { { ?m <"
			+ EX + "q> ?w } UNION { ?u <" + EX + "rU> ?w } } }";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			IRI q = vf.createIRI(EX, "q");
			IRI r = vf.createIRI(EX, "r");
			IRI pBad = vf.createIRI(EX, "pBad");
			IRI flag = vf.createIRI(EX, "flag");
			IRI rU = vf.createIRI(EX, "rU");
			IRI fNode = vf.createIRI(EX, "fNode");
			conn.begin();
			for (int i = 0; i < 400; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				IRI m = vf.createIRI(EX, "m" + i);
				conn.add(s, p, m);
				if (i % 2 == 0) {
					IRI w = vf.createIRI(EX, "w" + i);
					conn.add(m, q, w);
					conn.add(w, r, vf.createIRI(EX, "z" + i));
				}
				if (i % 3 == 0) {
					IRI y = vf.createIRI(EX, "y" + i);
					conn.add(s, pBad, y);
					conn.add(y, flag, fNode);
				}
			}
			// bag multiplicity: s0 carries a second p-edge whose chain also passes EXISTS
			IRI m0b = vf.createIRI(EX, "m0b");
			IRI w0b = vf.createIRI(EX, "w0b");
			conn.add(vf.createIRI(EX, "s0"), p, m0b);
			conn.add(m0b, q, w0b);
			conn.add(w0b, r, vf.createIRI(EX, "z0b"));
			// the UNION query's second branch is non-empty, so EXISTS is true for every row
			conn.add(vf.createIRI(EX, "u0"), rU, vf.createIRI(EX, "wU"));
			conn.commit();
		}
	}

	@AfterEach
	void tearDown() {
		System.clearProperty(NATIVE_FLAG);
		System.clearProperty(MARK_FLAG);
		repository.shutDown();
	}

	@Test
	void existsSubplanIsSweptOnceAndKeepsParity() {
		System.setProperty(NATIVE_FLAG, "false");
		List<String> expected = rows(EXISTS_QUERY);
		assertThat(expected).hasSize(201); // 200 even subjects + s0's second edge

		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(MARK_FLAG, "true");
		long buildsBefore = SubplanMarkProbe.SWEEP_BUILDS.get();
		long probesBefore = SubplanMarkProbe.SWEEP_PROBES.get();
		assertThat(rows(EXISTS_QUERY)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(SubplanMarkProbe.SWEEP_BUILDS.get() - buildsBefore)
				.as("the two-pattern EXISTS subplan must be swept exactly once")
				.isOne();
		assertThat(SubplanMarkProbe.SWEEP_PROBES.get() - probesBefore)
				.as("post-build probes must answer from the mark table")
				.isGreaterThan(0L);
	}

	@Test
	void notExistsSubplanIsSweptOnceAndKeepsParity() {
		System.setProperty(NATIVE_FLAG, "false");
		List<String> expected = rows(NOT_EXISTS_QUERY);
		assertThat(expected).hasSize(200); // odd subjects

		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(MARK_FLAG, "true");
		long buildsBefore = SubplanMarkProbe.SWEEP_BUILDS.get();
		assertThat(rows(NOT_EXISTS_QUERY)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(SubplanMarkProbe.SWEEP_BUILDS.get() - buildsBefore).isOne();
	}

	@Test
	void minusRightSideIsSweptOnceAndKeepsParity() {
		System.setProperty(NATIVE_FLAG, "false");
		List<String> expected = rows(MINUS_QUERY);
		assertThat(expected).hasSize(266); // 401 left rows minus the 135 whose subject has a pBad chain

		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(MARK_FLAG, "true");
		long buildsBefore = SubplanMarkProbe.SWEEP_BUILDS.get();
		long probesBefore = SubplanMarkProbe.SWEEP_PROBES.get();
		assertThat(rows(MINUS_QUERY)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(SubplanMarkProbe.SWEEP_BUILDS.get() - buildsBefore)
				.as("the two-pattern MINUS right side must be swept exactly once")
				.isOne();
		assertThat(SubplanMarkProbe.SWEEP_PROBES.get() - probesBefore).isGreaterThan(0L);
	}

	@Test
	void unionBranchLeavingKeyUnboundAbortsTheSweepAndFallsBack() {
		System.setProperty(NATIVE_FLAG, "false");
		List<String> expected = rows(UNION_EXISTS_QUERY);
		assertThat(expected).hasSize(401);

		System.setProperty(NATIVE_FLAG, "true");
		System.setProperty(MARK_FLAG, "true");
		long buildsBefore = SubplanMarkProbe.SWEEP_BUILDS.get();
		assertThat(rows(UNION_EXISTS_QUERY)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(SubplanMarkProbe.SWEEP_BUILDS.get() - buildsBefore)
				.as("a swept row with an unbound key slot must abandon the mark, never commit it")
				.isZero();
	}

	@Test
	void flagOffNeverBuildsOrProbes() {
		System.setProperty(NATIVE_FLAG, "true");
		long buildsBefore = SubplanMarkProbe.SWEEP_BUILDS.get();
		long probesBefore = SubplanMarkProbe.SWEEP_PROBES.get();
		assertThat(rows(EXISTS_QUERY)).hasSize(201);
		assertThat(rows(MINUS_QUERY)).hasSize(266);
		assertThat(SubplanMarkProbe.SWEEP_BUILDS.get() - buildsBefore).isZero();
		assertThat(SubplanMarkProbe.SWEEP_PROBES.get() - probesBefore).isZero();
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rows.add(String.join("|", parts));
				}
			}
		}
		return rows;
	}
}
